package com.harshith.leave.service; import com.harshith.leave.entity.*; import com.harshith.leave.exception.*; import com.harshith.leave.repository.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class EmployeeService { private final EmployeeRepository er; private final LeaveBalanceRepository br; public EmployeeService(EmployeeRepository er,LeaveBalanceRepository br){this.er=er;this.br=br;} public Employee create(Employee e){Employee s=er.save(e);br.save(new LeaveBalance(s));return s;} public List<Employee> all(){return er.findAll();} public Employee get(Long id){return er.findById(id).orElseThrow(()->new ResourceNotFoundException("Employee not found: "+id));} public Employee update(Long id,Employee d){Employee e=get(id);e.setName(d.getName());e.setEmail(d.getEmail());e.setDepartment(d.getDepartment());return er.save(e);} public void delete(Long id){er.delete(get(id));} public LeaveBalance balance(Long id){get(id);return br.findByEmployeeId(id).orElseThrow(()->new ResourceNotFoundException("Leave balance not found"));} }